-- Paket 13.11.2026 (5): compact catalogue cards on phones (new chunk HtsListCompact, template 18). Text is hex-encoded on purpose.
SET NAMES utf8mb4;
SET SESSION group_concat_max_len = 100000;
-- ROLLBACK: removes the one line from template 18 and the chunk.
UPDATE modx_site_templates t SET t.content = REPLACE(CONVERT(t.content USING utf8mb4), _utf8mb4 0x0A2020202020202020202020202020202020202020202020205B5B244874734C697374436F6D706163745D5D, '') WHERE t.id = 18;
UPDATE modx_site_templates t SET t.content = REPLACE(CONVERT(t.content USING utf8mb4), _utf8mb4 0x5B5B244874734C697374436F6D706163745D5D, '') WHERE t.id = 18;
DELETE FROM modx_site_htmlsnippets WHERE name = 'HtsListCompact' AND snippet LIKE '%htsListCompact%';
SELECT CASE WHEN (SELECT content FROM modx_site_templates WHERE id = 18) NOT LIKE '%[[$HtsListCompact]]%' AND (SELECT COUNT(*) FROM modx_site_htmlsnippets WHERE name = 'HtsListCompact') = 0 THEN _utf8mb4 0xD09AD0BED0BCD0BFD0B0D0BAD182D0BDD18BD0B920D0B2D0B8D0B420D183D0B1D180D0B0D0BD2C20D188D0B0D0B1D0BBD0BED0BD20D0B2D0BED0B7D0B2D180D0B0D189D191D0BD ELSE _utf8mb4 0xD09DD09520D0A1D09ED092D09FD090D094D090D095D0A220E2809420D181D182D0BED0BF2C20D181D0BAD180D0B8D0BDD188D0BED182 END AS itog;
